// SVG data URL of an icon filled with a QML color
function url(hex, color) {
    var s = svg[hex];
    if (!s)
        return "";
    var fill = "rgb(" + Math.round(color.r * 255) + "," + Math.round(color.g * 255) + "," + Math.round(color.b * 255) + ")";
    return "data:image/svg+xml;utf8," + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="' + s[0]
        + '"><path fill="' + fill + '" fill-opacity="' + color.a + '" d="' + s[1] + '"/></svg>');
}
